<?php
namespace App\Services;
use App\Exceptions\ApiException;
use App\Models\{Product,ProductBatch,Sale,SaleItem,SaleReturn,SaleReturnItem};
use App\Support\{ExactMath,Quantity,IncentiveMath};
use Carbon\CarbonImmutable;
class DemandForecastService {
 public function __construct(private StockService $stock){}
 public function report(array $input):array{try{return \Illuminate\Support\Facades\DB::transaction(fn()=>$this->calculate($input));}catch(\InvalidArgumentException|\OverflowException $e){throw new ApiException('VALIDATION_ERROR',$e->getMessage(),422);}}
 private function calculate(array $input):array{
  $from=CarbonImmutable::createFromFormat('!Y-m-d',$input['from'],'Africa/Dar_es_Salaam');$to=CarbonImmutable::createFromFormat('!Y-m-d',$input['to'],'Africa/Dar_es_Salaam');$days=(int)$from->diffInDays($to)+1;if($days>366||$to->toDateString()>now('Africa/Dar_es_Salaam')->toDateString())throw new ApiException('VALIDATION_ERROR','Use at most 366 calendar days through today.',422);
  $start=$from->utc();$end=$to->addDay()->utc();$sales=Sale::select('id');if(\Illuminate\Support\Facades\Schema::hasColumn('sales','occurred_at'))$sales->whereRaw('COALESCE(sales.occurred_at,sales.created_at) >= ? AND COALESCE(sales.occurred_at,sales.created_at) < ?',[$start,$end]);else$sales->where('created_at','>=',$start)->where('created_at','<',$end);$query=Product::where('is_active',true);if(isset($input['search']))$query->where('name','like','%'.addcslashes($input['search'],'\\%_').'%');$products=$query->orderBy('name')->orderBy('id')->paginate($input['per_page']??50);$rows=[];
  foreach($products as$p){$sold=$this->atoms(SaleItem::where('product_id',$p->id)->whereIn('sale_id',clone $sales)->sum('qty_atoms'));$returned=$this->atoms(SaleReturnItem::where('product_id',$p->id)->whereIn('sale_return_id',SaleReturn::select('id')->where('created_at','>=',$start)->where('created_at','<',$end))->sum('qty_atoms'));$net=max(0,$sold-$returned);$available=$this->atoms($this->stock->eligibleBatches(ProductBatch::where('product_id',$p->id))->sum('qty_remaining_atoms'));$negative=ProductBatch::where('product_id',$p->id)->where('qty_remaining_atoms','<',0)->exists();$target=IncentiveMath::ceilingDemand($net,$days,(int)$input['coverage_days']);$weighted=$p->quantity_type==='weight';
   $rows[]=['product_id'=>$p->publicId(),'product_name'=>$p->name,'unit'=>$p->unit,'quantity_type'=>$p->quantity_type,'sold_qty'=>Quantity::format($sold,$weighted),'returned_qty'=>Quantity::format($returned,$weighted),'net_demand_qty'=>Quantity::format($net,$weighted),'daily_demand_numerator_atoms'=>(string)$net,'daily_demand_denominator_days'=>$days,'quantity_scale'=>$weighted?1000:1,'eligible_stock'=>Quantity::format($available,$weighted),'coverage_target_qty'=>Quantity::format($target,$weighted),'suggested_reorder_qty'=>Quantity::format(max(0,$target-$available),$weighted),'flags'=>array_values(array_filter([$sold===0?'no_sales':null,$returned>$sold?'returns_exceed_window_sales':null,$days<7?'short_history_window':null,$negative?'unresolved_negative_stock':null]))];
  }
  return ['forecast'=>['from'=>$input['from'],'to'=>$input['to'],'timezone'=>'Africa/Dar_es_Salaam','days'=>$days,'coverage_days'=>(int)$input['coverage_days'],'method'=>'historical_net_quantity_daily_average','as_of'=>now()->toIso8601String(),'limitations'=>['Historical recorded demand only; does not model seasonality, lead time, supplier availability or lost sales.','Returns are attributed to their own event dates and may relate to sales outside this window.','Suggestions do not create purchases.'],'products'=>$rows],'meta'=>['page'=>$products->currentPage(),'per_page'=>$products->perPage(),'total'=>$products->total()]];
 }
 private function atoms($value):int{$digits=(string)$value;if(!preg_match('/^[0-9]+$/D',$digits)||strlen($digits)>strlen((string)PHP_INT_MAX)||(strlen($digits)===strlen((string)PHP_INT_MAX)&&strcmp($digits,(string)PHP_INT_MAX)>0))throw new ApiException('VALIDATION_ERROR','This demand quantity exceeds the exact supported range.',422);return (int)$digits;}
}
